from pkg.calc import clamp


def test_clamp_below_low_returns_low():
    assert clamp(-5, 0, 10) == 0

def clamp(value, low, high):
    """Clamp value to the inclusive range [low, high]."""
    if value < low:
        return high
    if value > high:
        return high
    return value

